import React, { useState, useEffect } from 'react';
import { getPagos, getCurrentUser, getTotalDeudaByJugador } from '../../database/db';
import './MisPagos.css';

function MisPagos() {
  const [pagos, setPagos] = useState([]);
  const [totalDeuda, setTotalDeuda] = useState(0);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      setUser(currentUser);
      
      if (currentUser) {
        const [todosPagos, deuda] = await Promise.all([
          getPagos(),
          getTotalDeudaByJugador(currentUser.Id)
        ]);
        
        const misPagos = todosPagos.filter(p => p.JugadorId === currentUser.Id);
        setPagos(misPagos);
        setTotalDeuda(deuda);
      }
    } catch (error) {
      console.error('Error cargando pagos:', error);
      alert('Error al cargar los pagos');
    }
    setLoading(false);
  };

  const getConceptoTexto = (concepto) => {
    return concepto === 'entrenamiento' ? '⚽ Entrenamiento' : '🏆 Partido';
  };

  // Obtener valores con soporte para ambos formatos
  const getEstado = (pago) => pago.Estado || pago.estado;
  const getMonto = (pago) => pago.Monto || pago.monto;
  const getFechaVencimiento = (pago) => pago.FechaVencimiento || pago.fecha_vencimiento;
  const getFechaPago = (pago) => pago.FechaPago || pago.fecha_pago;
  const getReferenciaId = (pago) => pago.ReferenciaId || pago.referencia_id;
  const getMetodoPago = (pago) => pago.MetodoPago || pago.metodo_pago;

  const pagosPendientes = pagos.filter(p => getEstado(p) === 'pendiente');
  const pagosRealizados = pagos.filter(p => getEstado(p) === 'pagado');

  if (loading) {
    return (
      <div className="mis-pagos">
        <div className="loading-container">Cargando pagos...</div>
      </div>
    );
  }

  return (
    <div className="mis-pagos">
      <h2><i className="fas fa-dollar-sign"></i> Mis Pagos</h2>

      {/* Resumen de deuda */}
      <div className="deuda-card">
        <div className="deuda-total">
          <i className="fas fa-exclamation-circle"></i>
          <div>
            <span>Total pendiente</span>
            <h3>${totalDeuda.toLocaleString()}</h3>
          </div>
        </div>
        <div className="deuda-resumen">
          <div className="resumen-item">
            <span>Pendientes:</span>
            <strong>{pagosPendientes.length}</strong>
          </div>
          <div className="resumen-item">
            <span>Pagados:</span>
            <strong>{pagosRealizados.length}</strong>
          </div>
        </div>
      </div>

      {/* Pagos Pendientes */}
      {pagosPendientes.length > 0 && (
        <div className="seccion-pagos">
          <h3><i className="fas fa-clock"></i> Pagos Pendientes</h3>
          <div className="pagos-lista">
            {pagosPendientes.map(pago => (
              <div key={pago.Id} className="pago-card pendiente">
                <div className="pago-header">
                  <span className="concepto">{getConceptoTexto(pago.Concepto)}</span>
                  <span className="monto-pendiente">${getMonto(pago).toLocaleString()}</span>
                </div>
                <div className="pago-body">
                  <p><i className="fas fa-calendar"></i> Vence: {getFechaVencimiento(pago) ? new Date(getFechaVencimiento(pago)).toLocaleDateString() : '-'}</p>
                  <p><i className="fas fa-info-circle"></i> Referencia #{getReferenciaId(pago)}</p>
                </div>
                <div className="pago-footer">
                  <span className="estado-pendiente">⏳ Pendiente de pago</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Historial de Pagos */}
      {pagosRealizados.length > 0 && (
        <div className="seccion-pagos">
          <h3><i className="fas fa-history"></i> Historial de Pagos</h3>
          <div className="pagos-lista">
            {pagosRealizados.map(pago => (
              <div key={pago.Id} className="pago-card pagado">
                <div className="pago-header">
                  <span className="concepto">{getConceptoTexto(pago.Concepto)}</span>
                  <span className="monto-pagado">${getMonto(pago).toLocaleString()}</span>
                </div>
                <div className="pago-body">
                  <p><i className="fas fa-calendar-check"></i> Pagado: {getFechaPago(pago) ? new Date(getFechaPago(pago)).toLocaleDateString() : '-'}</p>
                  <p><i className="fas fa-credit-card"></i> Método: {getMetodoPago(pago) === 'qr' ? 'QR / Escáner' : (getMetodoPago(pago) || '-')}</p>
                </div>
                <div className="pago-footer">
                  <span className="estado-pagado">✅ Pagado</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {pagos.length === 0 && (
        <div className="empty-state">
          <i className="fas fa-receipt"></i>
          <p>No hay registros de pagos</p>
        </div>
      )}
    </div>
  );
}

export default MisPagos;
